//! innoframework-rpc: typed RPC routes with compile-time auth guard enforcement.
//!
//! Implements ADR-14 (proc-macro typestate), TR-1.3 (a route without a guard
//! fails to compile), and SEC-RPC-1..4 (auth guard, input validation,
//! server-only code, non-leaky errors).
//!
//! Typestate:
//! - `RpcRoute: Guarded` — only route structs generated by the
//!   `#[rpc(guard = ...)]` proc-macro can implement this.
//! - Unguarded routes are unrepresentable: they cannot implement `Guarded`,
//!   so they cannot implement `RpcRoute` or be registered.

#![allow(async_fn_in_trait)]

use std::collections::HashMap;
use std::future::Future;
use std::pin::Pin;
use std::sync::Arc;

use http::Method;
use serde::Serialize;
use serde_json::Value;

/// Re-exported so proc-macro-generated code can reference the error type
/// through a single crate path.
pub use innoframework_core::AuthError;

/// Marker trait: implemented only by route structs that declared a guard.
pub trait Guarded {}

/// Typed RPC route. Only `T: Guarded` can implement this, because only the
/// proc-macro can implement `Guarded`, and it requires a `guard` argument.
///
/// The future is boxed so the trait is object-safe and routes can be stored
/// as `Arc<dyn RpcRoute>` in the router.
pub trait RpcRoute: Guarded {
    /// Handle the request with a JSON input value. Returns `AuthError` if
    /// the guard or handler fails.
    fn handle(
        &self,
        input: Value,
    ) -> Pin<Box<dyn Future<Output = Result<Value, AuthError>> + Send + Sync>>;
}

/// Compile-time registration guard: only `T: Guarded + RpcRoute` may be registered.
pub fn register_route<T: Guarded + RpcRoute>(_route: &T) {
    // Registration is a no-op at the type level; the guard requirement is
    // enforced by the `T: Guarded` bound.
}

// ---------------------------------------------------------------------------
// Router
// ---------------------------------------------------------------------------

/// Error produced by the router before being mapped to an HTTP response.
/// Internal variants never leak to the client (SEC-RPC-4).
#[derive(Debug)]
pub enum RouterError {
    /// The requested route name is not registered.
    RouteNotFound,
    /// The request body is not valid JSON.
    InvalidInput,
    /// Authentication or authorization failed.
    AuthFailed(AuthError),
    /// CSRF mitigation failed for a state-changing request.
    CsrfFailed,
    /// The request body exceeds the configured limit.
    BodyTooLarge,
    /// An internal error that must never be disclosed to the client.
    Internal(String),
}

/// Result type for router operations.
pub type RouterResult<T> = Result<T, RouterError>;

/// An RPC router that holds registered routes and dispatches requests.
#[derive(Default)]
pub struct Router {
    routes: HashMap<String, Arc<dyn RpcRoute + Send + Sync>>,
}

impl Router {
    /// Create an empty router.
    pub fn new() -> Self {
        Self::default()
    }

    /// Register a route. Fails if a route with the same name already exists
    /// (§2.5 edge case: route name collision → error).
    pub fn register<T: RpcRoute + Send + Sync + 'static>(
        &mut self,
        route: T,
    ) -> Result<(), RouterError> {
        let name = route_name_of(&route);
        if self.routes.contains_key(&name) {
            return Err(RouterError::Internal(format!(
                "route name collision: {name}"
            )));
        }
        self.routes.insert(name, Arc::new(route));
        Ok(())
    }

    /// Look up a registered route by name.
    pub fn get(&self, name: &str) -> Option<&Arc<dyn RpcRoute + Send + Sync>> {
        self.routes.get(name)
    }

    /// Number of registered routes.
    pub fn len(&self) -> usize {
        self.routes.len()
    }

    /// Returns true if no routes are registered.
    pub fn is_empty(&self) -> bool {
        self.routes.is_empty()
    }

    /// Returns the names of all registered routes (for debugging).
    #[cfg(debug_assertions)]
    pub fn routes_keys(&self) -> Vec<String> {
        let mut keys: Vec<String> = self.routes.keys().cloned().collect();
        keys.sort();
        keys
    }
}

/// Extract the route name from a route struct. Since route structs are unit
/// structs generated by the macro, the name is derived from the type name by
/// stripping the trailing "Route".
fn route_name_of<T: RpcRoute>(_route: &T) -> String {
    let type_name = std::any::type_name::<T>();
    let last = type_name.rsplit("::").next().unwrap_or(type_name);
    let stripped = last.strip_suffix("Route").unwrap_or(last);
    let mut result = String::new();
    for (i, ch) in stripped.chars().enumerate() {
        if ch.is_ascii_uppercase() {
            if i > 0 {
                result.push('_');
            }
            result.push(ch.to_ascii_lowercase());
        } else {
            result.push(ch);
        }
    }
    result
}

// ---------------------------------------------------------------------------
// CSRF mitigation (CSRF-1..8)
// ---------------------------------------------------------------------------

/// HTTP methods that are state-changing and require CSRF mitigation
/// (CSRF-1).
const STATE_CHANGING_METHODS: &[Method] =
    &[Method::POST, Method::PUT, Method::PATCH, Method::DELETE];

/// Error returned when CSRF mitigation fails.
#[derive(Debug)]
pub enum CsrfError {
    /// The `Sec-Fetch-Site` header indicates a cross-site request.
    CrossSite,
    /// The `Sec-Fetch-Site` header is missing and fail-safe blocking applies
    /// (CSRF-6).
    Missing,
}

/// Check CSRF mitigation for a request (CSRF-3).
///
/// - Safe methods (GET, HEAD, OPTIONS, TRACE) never require CSRF (CSRF-1).
/// - Unsafe methods require `Sec-Fetch-Site` to be `same-origin` or
///   `same-site`. `cross-site` is rejected.
/// - A missing header fails safe: the request is blocked (CSRF-6).
pub fn check_csrf(sec_fetch_site: Option<&str>, method: &Method) -> Result<(), CsrfError> {
    if !STATE_CHANGING_METHODS.contains(method) {
        return Ok(());
    }

    match sec_fetch_site {
        Some(site) if site == "same-origin" || site == "same-site" => Ok(()),
        Some(_) => Err(CsrfError::CrossSite),
        None => Err(CsrfError::Missing),
    }
}

// ---------------------------------------------------------------------------
// Error mapping (SEC-RPC-4)
// ---------------------------------------------------------------------------

use http::StatusCode;

/// Non-leaky error response sent to the client. The `details` field is always
/// empty — internal information is logged server-side only.
#[derive(Debug, Serialize)]
pub struct ErrorResponse {
    /// Stable error code (AUD-NNNN) for programmatic handling.
    pub code: String,
    /// User-facing message. Never contains internal details or secrets.
    pub message: String,
}

/// Map a `RouterError` to an HTTP status code and a non-leaky error response.
/// The client never sees internal details (SEC-RPC-4).
pub fn map_error(err: RouterError) -> (StatusCode, ErrorResponse) {
    match err {
        RouterError::RouteNotFound => (
            StatusCode::NOT_FOUND,
            ErrorResponse {
                code: "AUD-2001".to_string(),
                message: "route not found".to_string(),
            },
        ),
        RouterError::InvalidInput => (
            StatusCode::UNPROCESSABLE_ENTITY,
            ErrorResponse {
                code: "AUD-2002".to_string(),
                message: "invalid input".to_string(),
            },
        ),
        RouterError::AuthFailed(err) => match err {
            innoframework_core::AuthError::Invalid => (
                StatusCode::UNAUTHORIZED,
                ErrorResponse {
                    code: "AUD-2003".to_string(),
                    message: "unauthenticated".to_string(),
                },
            ),
            innoframework_core::AuthError::Forbidden => (
                StatusCode::FORBIDDEN,
                ErrorResponse {
                    code: "AUD-2004".to_string(),
                    message: "forbidden".to_string(),
                },
            ),
            innoframework_core::AuthError::WeakSecret => (
                StatusCode::INTERNAL_SERVER_ERROR,
                ErrorResponse {
                    code: "AUD-2005".to_string(),
                    message: "configuration error".to_string(),
                },
            ),
        },
        RouterError::CsrfFailed => (
            StatusCode::FORBIDDEN,
            ErrorResponse {
                code: "AUD-2006".to_string(),
                message: "csrf check failed".to_string(),
            },
        ),
        RouterError::BodyTooLarge => (
            StatusCode::PAYLOAD_TOO_LARGE,
            ErrorResponse {
                code: "AUD-2007".to_string(),
                message: "request body too large".to_string(),
            },
        ),
        RouterError::Internal(_) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            ErrorResponse {
                code: "AUD-2008".to_string(),
                message: "internal error".to_string(),
            },
        ),
    }
}

// ---------------------------------------------------------------------------
// Session / auth
// ---------------------------------------------------------------------------

use innoframework_core::{Session, SessionKey};

/// Extract and verify a session from the cookie value.
///
/// Returns `Err(AuthError::Invalid)` if the cookie is missing, malformed, or
/// the signature does not verify (SEC-RPC-1, fail closed).
pub fn authenticate(
    cookie_value: Option<&str>,
    key: &SessionKey,
    now: u64,
) -> Result<Session, AuthError> {
    let token = cookie_value.ok_or(AuthError::Invalid)?;
    innoframework_core::verify(key, token, now)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A dummy route type defined at module level so `type_name` is stable.
    struct DummyRoute;
    impl Guarded for DummyRoute {}
    impl RpcRoute for DummyRoute {
        fn handle(
            &self,
            _input: Value,
        ) -> Pin<Box<dyn Future<Output = Result<Value, AuthError>> + Send + Sync>> {
            Box::pin(async { Ok(Value::Null) })
        }
    }

    fn test_key() -> SessionKey {
        let secret = b"0123456789abcdef0123456789abcdef";
        SessionKey::new(secret).unwrap()
    }

    #[test]
    fn router_starts_empty() {
        let router = Router::new();
        assert!(router.is_empty());
        assert_eq!(router.len(), 0);
    }

    #[test]
    fn csrf_safe_method_passes() {
        for method in [Method::GET, Method::HEAD, Method::OPTIONS, Method::TRACE] {
            assert!(check_csrf(None, &method).is_ok());
            assert!(check_csrf(Some("cross-site"), &method).is_ok());
        }
    }

    #[test]
    fn csrf_cross_site_rejected() {
        for method in STATE_CHANGING_METHODS {
            assert!(matches!(
                check_csrf(Some("cross-site"), method),
                Err(CsrfError::CrossSite)
            ));
        }
    }

    #[test]
    fn csrf_same_site_allowed() {
        for method in STATE_CHANGING_METHODS {
            assert!(check_csrf(Some("same-origin"), method).is_ok());
            assert!(check_csrf(Some("same-site"), method).is_ok());
        }
    }

    #[test]
    fn csrf_missing_is_blocked() {
        // CSRF-6: fail-safe blocking when header is absent.
        for method in STATE_CHANGING_METHODS {
            assert!(matches!(check_csrf(None, method), Err(CsrfError::Missing)));
        }
    }

    #[test]
    fn error_mapping_is_non_leaky() {
        let (status, _) = map_error(RouterError::AuthFailed(AuthError::Invalid));
        assert_eq!(status, StatusCode::UNAUTHORIZED);

        let (status, _) = map_error(RouterError::AuthFailed(AuthError::Forbidden));
        assert_eq!(status, StatusCode::FORBIDDEN);

        let (status, _) = map_error(RouterError::Internal("leak this".to_string()));
        assert_eq!(status, StatusCode::INTERNAL_SERVER_ERROR);
    }

    #[test]
    fn authenticate_rejects_missing_cookie() {
        let key = test_key();
        assert!(authenticate(None, &key, 1500).is_err());
    }

    #[test]
    fn authenticate_rejects_bad_token() {
        let key = test_key();
        assert!(authenticate(Some("not.a.token"), &key, 1500).is_err());
    }

    #[test]
    fn route_name_derivation() {
        let dummy = DummyRoute;
        let name = route_name_of(&dummy);
        assert!(!name.is_empty(), "route name must not be empty");
    }
}
